  it.live.each(["native", "legacy", "replacement-unsupported"] as const)(
    "starts a replacement native thread as new after the resume fallback with %s attempts",
    (attempts) =>
      Effect.gen(function* () {
        const cwd = yield* checkpointWorkspace("resume-fallback-native-turns");
        const capturedTurns = yield* Ref.make<ReadonlyArray<CapturedTurn>>([]);
        const failResumeOnce = yield* Ref.make(false);
        const generation = yield* Ref.make(0);
        const layerRegistry = ProviderAdapterRegistry.layerFromAdapters([
          makeTestAdapter({
            instanceId: CLAUDE_MODEL_SELECTION.instanceId,
            driver: CLAUDE_DRIVER,
            capabilities: ClaudeProviderCapabilitiesV2,
            modelSelection: CLAUDE_MODEL_SELECTION,
            responseByRunOrdinal: {},
            capturedTurns,
            failResumeOnce,
            nativeThreadGeneration: generation,
            ...(attempts === "replacement-unsupported"
              ? { supportsNativeThreadReplacement: false, failResume: true }
              : {}),
          }),
        ]);
        yield* Effect.gen(function* () {
          const orchestrator = yield* Orchestrator.OrchestratorV2;
          const worker = yield* EffectWorker.OrchestrationEffectWorkerV2;
          const runToCompletion = Effect.fn("runToCompletion")(function* (
            ordinal: number,
            status = "completed",
          ) {
            yield* orchestrator.dispatch({
              type: "message.dispatch",
              commandId: CommandId.make(`resume-fallback:${ordinal}`),
              threadId,
              messageId: MessageId.make(`resume-fallback:${ordinal}`),
              createdBy: "user",
              creationSource: "web",
              text: `Request ${ordinal}`,
              attachments: [],
              modelSelection: CLAUDE_MODEL_SELECTION,
              dispatchMode: { type: "start_immediately" },
            });
            yield* orchestrator.streamStoredEvents.pipe(
              Stream.filter(
                ({ event }) =>
                  event.type === "run.updated" &&
                  event.payload.ordinal === ordinal &&
                  (event.payload.status === "completed" || event.payload.status === "failed"),
              ),
              Stream.runHead,
            );
            yield* worker.drain();
            assert.equal(
              (yield* orchestrator.getThreadProjection(threadId)).runs.at(-1)?.status,
              status,
            );
          });
          yield* orchestrator.dispatch({
            type: "thread.create",
            commandId: CommandId.make("resume-fallback:create"),
            threadId,
            projectId,
            createdBy: "user",
            creationSource: "web",
            title: "Resume fallback",
            modelSelection: CLAUDE_MODEL_SELECTION,
            runtimeMode: "full-access",
            interactionMode: "default",
            branch: null,
            worktreePath: null,
          });
          yield* runToCompletion(1);
          const providerThread = (yield* orchestrator.getThreadProjection(
            threadId,
          )).providerThreads.at(0);
          if (providerThread === undefined || providerThread.providerSessionId === null) {
            return yield* Effect.die("Expected a provider session after the first turn.");
          }
          yield* orchestrator.dispatch({
            type: "provider-session.detach",
            commandId: CommandId.make("resume-fallback:detach"),
            threadId,
            providerSessionId: providerThread.providerSessionId,
          });
          yield* worker.drain();
          if (attempts === "legacy") {
            const existing = yield* orchestrator.getThreadProjection(threadId);
            yield* (yield* EventSink.EventSinkV2).write({
              events: existing.attempts.map(
                ({ nativeThreadId: _nativeThreadId, ...legacy }, index) => ({
                  id: EventId.make(`resume-fallback-legacy-attempt:${index}`),
                  type: "run-attempt.updated" as const,
                  threadId,
                  occurredAt: existing.thread.createdAt,
                  payload: legacy,
                }),
              ),
            });
          }
          yield* Ref.set(failResumeOnce, true);
          yield* runToCompletion(
            2,
            attempts === "replacement-unsupported" ? "failed" : "completed",
          );
          if (attempts === "replacement-unsupported") {
            const failure = (yield* orchestrator.getThreadProjection(threadId)).turnItems.findLast(
              (item) => item.type === "error",
            );
            assert.notInclude(
              failure?.type === "error" ? failure.failure.message : "",
