            assert.equal(yield* Ref.get(generation), 1);
            assert.equal(
              (yield* orchestrator.getThreadProjection(threadId)).providerThreads[0]
                ?.nativeThreadRef?.nativeId,
              turns[0]?.nativeThreadId,
