        });
        yield* send(1, CLAUDE_MODEL_SELECTION);

        if (queued) {
          yield* Deferred.await(firstStarted);
          yield* send(2, secondSelection);
          const queuedRunId = (yield* orchestrator.getThreadProjection(handoffThreadId)).runs[1]
            ?.id;
