          assert.lengthOf(yield* Ref.get(capturedTurns), 1);
          yield* Ref.set(backgroundWork, false);
          yield* orchestrator.dispatch({
            type: "queue.resume",
            commandId: CommandId.make("command:handoff-releases-session:resume"),
            threadId: handoffThreadId,
